type SocialServiceHTTPClient interface {
	// AcceptFriendRequest 同意好友申请，只有接收方可以操作。
	AcceptFriendRequest(ctx context.Context, req *AcceptFriendRequestRequest, opts ...http.CallOption) (rsp *AcceptFriendRequestResponse, err error)
	// AcceptGroupJoinRequest 同意入群申请（群主、管理员）。
	AcceptGroupJoinRequest(ctx context.Context, req *AcceptGroupJoinRequestRequest, opts ...http.CallOption) (rsp *AcceptGroupJoinRequestResponse, err error)
	// AddGroupMembers 邀请好友入群（群主、管理员），不需要审核；已是成员的人跳过。
	AddGroupMembers(ctx context.Context, req *AddGroupMembersRequest, opts ...http.CallOption) (rsp *AddGroupMembersResponse, err error)
	// BlockUser 拉黑用户。不删除好友关系；任何一方拉黑另一方后，双方都不能单聊、不能互发好友申请。重复拉黑返回成功。
	BlockUser(ctx context.Context, req *BlockUserRequest, opts ...http.CallOption) (rsp *BlockUserResponse, err error)
	// CreateGroup 创建群，可以带上初始成员（必须是创建者的好友）。
	CreateGroup(ctx context.Context, req *CreateGroupRequest, opts ...http.CallOption) (rsp *CreateGroupResponse, err error)
	// DeleteFriend 删除好友，双方的关系同时删除。对方不是好友时也返回成功。
	DeleteFriend(ctx context.Context, req *DeleteFriendRequest, opts ...http.CallOption) (rsp *DeleteFriendResponse, err error)
	// DismissGroup 解散群（群主或系统管理员）。
	DismissGroup(ctx context.Context, req *DismissGroupRequest, opts ...http.CallOption) (rsp *DismissGroupResponse, err error)
	// GetGroup 获取群资料。非成员看不到群公告；已解散的群仍可查询。
	GetGroup(ctx context.Context, req *GetGroupRequest, opts ...http.CallOption) (rsp *GetGroupResponse, err error)
	// JoinGroup 加入群。直接加入的群立即入群；需审核的群生成入群申请。
	JoinGroup(ctx context.Context, req *JoinGroupRequest, opts ...http.CallOption) (rsp *JoinGroupResponse, err error)
	// LeaveGroup 退出群。群主需要先转让群主。
	LeaveGroup(ctx context.Context, req *LeaveGroupRequest, opts ...http.CallOption) (rsp *LeaveGroupResponse, err error)
	// ListBlockedUsers 列出我拉黑的用户，按用户 ID 递增。
	ListBlockedUsers(ctx context.Context, req *ListBlockedUsersRequest, opts ...http.CallOption) (rsp *ListBlockedUsersResponse, err error)
	// ListFriends 列出好友，按用户 ID 递增。
	ListFriends(ctx context.Context, req *ListFriendsRequest, opts ...http.CallOption) (rsp *ListFriendsResponse, err error)
	// ListGroupJoinRequests 列出群的待处理入群申请（群主、管理员），按时间倒序。
	ListGroupJoinRequests(ctx context.Context, req *ListGroupJoinRequestsRequest, opts ...http.CallOption) (rsp *ListGroupJoinRequestsResponse, err error)
	// ListGroupMembers 列出群成员（仅成员可见），按用户 ID 递增。
	ListGroupMembers(ctx context.Context, req *ListGroupMembersRequest, opts ...http.CallOption) (rsp *ListGroupMembersResponse, err error)
	// ListMyGroups 列出我加入的群，按群 ID 递增。
	ListMyGroups(ctx context.Context, req *ListMyGroupsRequest, opts ...http.CallOption) (rsp *ListMyGroupsResponse, err error)
	// ListReceivedFriendRequests 列出收到的待处理好友申请，按时间倒序。
	ListReceivedFriendRequests(ctx context.Context, req *ListReceivedFriendRequestsRequest, opts ...http.CallOption) (rsp *ListReceivedFriendRequestsResponse, err error)
	// ListSentFriendRequests 列出发出的好友申请（全部状态），按时间倒序。
	ListSentFriendRequests(ctx context.Context, req *ListSentFriendRequestsRequest, opts ...http.CallOption) (rsp *ListSentFriendRequestsResponse, err error)
	// MuteGroupMember 禁言或解除禁言。群主可以禁言管理员和成员，管理员只能禁言成员。
	MuteGroupMember(ctx context.Context, req *MuteGroupMemberRequest, opts ...http.CallOption) (rsp *MuteGroupMemberResponse, err error)
	// RejectFriendRequest 拒绝好友申请，只有接收方可以操作。
	RejectFriendRequest(ctx context.Context, req *RejectFriendRequestRequest, opts ...http.CallOption) (rsp *RejectFriendRequestResponse, err error)
	// RejectGroupJoinRequest 拒绝入群申请（群主、管理员）。
	RejectGroupJoinRequest(ctx context.Context, req *RejectGroupJoinRequestRequest, opts ...http.CallOption) (rsp *RejectGroupJoinRequestResponse, err error)
	// RemoveGroupMember 移除群成员。群主可以移除管理员和成员，管理员只能移除成员。
	RemoveGroupMember(ctx context.Context, req *RemoveGroupMemberRequest, opts ...http.CallOption) (rsp *RemoveGroupMemberResponse, err error)
	// SendFriendRequest 申请添加好友。对方已经向我发出待处理申请时直接成为好友；已有我发出的待处理申请时更新附言。
	SendFriendRequest(ctx context.Context, req *SendFriendRequestRequest, opts ...http.CallOption) (rsp *SendFriendRequestResponse, err error)
	// SetGroupMemberRole 设置或取消管理员（群主）。
	SetGroupMemberRole(ctx context.Context, req *SetGroupMemberRoleRequest, opts ...http.CallOption) (rsp *SetGroupMemberRoleResponse, err error)
	// TransferGroupOwner 转让群主（群主）。新群主必须是成员，原群主变为管理员。
	TransferGroupOwner(ctx context.Context, req *TransferGroupOwnerRequest, opts ...http.CallOption) (rsp *TransferGroupOwnerResponse, err error)
	// UnblockUser 解除拉黑。没有拉黑时也返回成功。
	UnblockUser(ctx context.Context, req *UnblockUserRequest, opts ...http.CallOption) (rsp *UnblockUserResponse, err error)
	// UpdateGroup 修改群资料（群主、管理员），只修改请求中出现的字段。version 与当前版本不一致时返回 GROUP_VERSION_CONFLICT。
	UpdateGroup(ctx context.Context, req *UpdateGroupRequest, opts ...http.CallOption) (rsp *UpdateGroupResponse, err error)
}

